    {
      id = "meditation",
      title = "Meditation: regen while casting",
      body = "Meditation (Discipline talent) lets part of your Spirit regen keep going while you cast. Forever increased its value, which makes it one of the biggest mana talents for every spec.",
      unconfirmed = false,
      flag = "Icy Veins says 50%; Wowhead's Holy formula uses 15% - check the in-game tooltip",
      sources = { "https://news.blizzard.com/en-us/article/24301514/world-of-warcraft-forever-class-deep-dives-priest-and-warrior", "https://www.icy-veins.com/wow-forever/shadow-priest-leveling", "https://www.icy-veins.com/wow-forever/discipline-priest-leveling" },
    },
    {
      id = "downranking",
      title = "Spell ranks and downranking",
      body = "Most spells have ranks you buy from the Priest trainer; higher ranks hit or heal harder but cost more mana. Downranking means casting a lower rank to save mana when the full rank would overheal, usually with Heal and Greater Heal. Ranks far below your level get less benefit from spell power, though Forever removed most talent penalties for low ranks.",
      unconfirmed = true,
      flag = "Exact penalty unclear: Blizzard says 'vastly below' your level, Wowhead Discipline says 18 levels, and Wowhead Holy says the penalty is smaller than Classic's",
      sources = { "https://us.forums.blizzard.com/en/wow/t/wow-forever-beta-development-notes-%E2%80%93-updated-november-2/2360696", "https://www.wowhead.com/forever/guide/classes/priest/holy/rotation-cooldowns-pve-healer", "https://www.wowhead.com/forever/guide/classes/priest/discipline/rotation-cooldowns-pve-healer", "https://www.icy-veins.com/wow-forever/holy-priest-healer-pve-guide" },
    },
    {
      id = "training-costs",
      title = "Visiting the trainer",
      body = "New spells and ranks show up every even level. Training everything from 1 to 60 costs about 206-207 gold, and Priest racial spells have their own prices. If gold is short, Shadow can skip Smite and Holy Fire ranks. Learned spells are no longer added to your action bars automatically.",
      unconfirmed = false,
      flag = "",
      sources = { "https://us.forums.blizzard.com/en/wow/t/wow-forever-beta-development-notes-%E2%80%93-updated-november-2/2360696", "https://www.icy-veins.com/wow-forever/shadow-priest-leveling", "https://www.wowhead.com/forever/guide/classes/priest/shadow/leveling-tips" },
    },
    {
      id = "weakened-soul",
      title = "Power Word: Shield and Weakened Soul",
      body = "Power Word: Shield puts Weakened Soul on its target, which stops another shield until it wears off. In Forever, a shield of equal or higher rank can replace an existing shield on a target without Weakened Soul. Human Divine Grace removes Weakened Soul, and Discipline's Renewed Hope shortens it.",
      unconfirmed = false,
      flag = "",
      sources = { "https://www.icy-veins.com/wow-forever/shadow-priest-leveling", "https://www.wowhead.com/forever/guide/classes/priest/discipline/rotation-cooldowns-pve-healer", "https://us.forums.blizzard.com/en/wow/t/wow-forever-beta-development-notes-%E2%80%93-updated-november-2/2360696", "https://news.blizzard.com/en-us/article/24301514/world-of-warcraft-forever-class-deep-dives-priest-and-warrior" },
    },
    {
      id = "spell-pushback",
      title = "Spell pushback",
      body = "Taking damage while you cast pushes your cast bar back. A channel like Mind Flay gets cut short instead. Damage absorbed by Power Word: Shield causes no pushback, and Twilight Focus greatly reduces it.",
      unconfirmed = false,
      flag = "",
      sources = { "https://www.icy-veins.com/wow-forever/shadow-priest-leveling", "https://www.icy-veins.com/wow-forever/shadow-priest-ranged-dps-pve-guide" },
    },
    {
      id = "threat-and-fade",
      title = "Threat and Fade",
      body = "Healing, Mind Blast, Devouring Plague and Vampiric Embrace all cause threat. Forever doubled Fade's threat reduction, but it's temporary: when it ends, the threat comes back. Silent Resolve and Shadow Affinity lower the threat you cause.",
      unconfirmed = false,
      flag = "",
      sources = { "https://news.blizzard.com/en-us/article/24301514/world-of-warcraft-forever-class-deep-dives-priest-and-warrior", "https://us.forums.blizzard.com/en/wow/t/wow-forever-beta-development-notes-%E2%80%93-updated-november-2/2360696", "https://www.wowhead.com/forever/guide/classes/priest/shadow/leveling-tips", "https://www.wowhead.com/forever/guide/classes/priest/shadow/abilities", "https://www.icy-veins.com/wow-forever/priest-class-overview" },
    },
    {
      id = "wands",
      title = "Wands",
      body = "Your wand costs no mana, and early on it does roughly 40-50% of your damage. In Forever, wands don't get stronger from spell damage, and you must stand still for 0.5 seconds before shooting. Enchanters can craft early wands (Novice's Practice Wand at 1, Lesser Magic Wand at 5, Greater Magic Wand at 13).",
      unconfirmed = false,
      flag = "",
      sources = { "https://us.forums.blizzard.com/en/wow/t/wow-forever-beta-development-notes-%E2%80%93-updated-november-2/2360696", "https://www.icy-veins.com/wow-forever/shadow-priest-leveling", "https://www.wowhead.com/forever/guide/classes/priest/shadow/leveling-tips", "https://www.icy-veins.com/wow-forever/professions-overview" },
    },
    {
      id = "spirit-tap",
      title = "Spirit Tap",
      body = "Spirit Tap (Shadow talent) triggers when you get the killing blow on a worthwhile enemy, or when an enemy with your Vampiric Embrace dies. While it's active your Spirit goes up and your mana keeps regenerating while you cast. It's the heart of Priest leveling.",
      unconfirmed = false,
      flag = "",
      sources = { "https://www.icy-veins.com/wow-forever/shadow-priest-leveling", "https://www.icy-veins.com/wow-forever/priest-class-overview", "https://www.wowhead.com/forever/guide/classes/priest/shadow/leveling-tips" },
    },
    {
      id = "shadowform",
      title = "Shadowform",
      body = "A level-40 Shadow talent: Shadow spells cost half the mana and crit harder. You can cast any non-healing spell (including Holy damage spells) but no heals, and since Nov 3 Cure Disease and Abolish Disease don't knock you out of it. Losing a little damage to heal in an emergency is better than wiping.",
      unconfirmed = false,
      flag = "",
      sources = { "https://news.blizzard.com/en-us/article/24301514/world-of-warcraft-forever-class-deep-dives-priest-and-warrior", "https://us.forums.blizzard.com/en/wow/t/wow-forever-beta-development-notes-%E2%80%93-updated-november-2/2360696", "https://www.icy-veins.com/wow-forever/shadow-priest-ranged-dps-pve-guide", "https://www.icy-veins.com/wow-forever/priest-class-overview" },
    },
    {
      id = "healing-power-damage",
      title = "Healing power also gives damage",
      body = "In Forever, bonus healing on gear also gives about one-third as much bonus spell damage. Spiritual Guidance works the same way, with a reduced damage share.",
      unconfirmed = true,
      flag = "The gear conversion is from Wowhead's stat guides; Blizzard only confirms Spiritual Guidance's one-third split",
      sources = { "https://www.wowhead.com/forever/guide/classes/priest/holy/stat-priority-pve-healer", "https://www.wowhead.com/forever/guide/classes/priest/discipline/stat-priority-pve-healer", "https://news.blizzard.com/en-us/article/24301514/world-of-warcraft-forever-class-deep-dives-priest-and-warrior" },
    },
    {
      id = "talents-milestones",
      title = "Talents, milestones and respecs",
      body = "You get your first talent point at 10. Each tree has one-point milestone talents at 11, 16, 21 and 31 points (for example Penance at 21 and Shadowform at 31). To change talents, including Legacy talents, visit a Priest trainer in a major city. Icy Veins quotes 1 gold for a respec.",
      unconfirmed = false,
      flag = "",
      sources = { "https://news.blizzard.com/en-us/article/24301514/world-of-warcraft-forever-class-deep-dives-priest-and-warrior", "https://www.icy-veins.com/wow-forever/shadow-priest-leveling", "https://www.icy-veins.com/wow-forever/discipline-priest-leveling" },
    },
    {
      id = "dual-spec",
      title = "Dual specialization",
      body = "At level 40 you can learn Dual Specialization at your class trainer: two talent setups you can swap between, for example Shadow for questing and Holy or Discipline for dungeons. Andric's Addon follows it: talent spec 1 uses profile A and talent spec 2 uses profile B, each with its own spec choice, gear weights and rotation.",
      unconfirmed = false,
      flag = "",
      sources = { "https://news.blizzard.com/en-us/article/24301514/world-of-warcraft-forever-class-deep-dives-priest-and-warrior" },
    },
    {
      id = "legacy-talents",
      title = "Legacy talents",
      body = "Legacy Challenges (leveling classes, professions, PvP, dungeons, raids) earn Legacy Points. You spend them on Legacy talents such as Well Rested and Talented for leveling, The Quick and the Dead (fixed Nov 6), and High Alert for PvP realms. You change them at a trainer, like normal talents.",
      unconfirmed = false,
      flag = "",
      sources = { "https://www.icy-veins.com/wow-forever/legacy-system", "https://www.wowhead.com/forever/guide/classes/priest/shadow/leveling-tips", "https://www.wowhead.com/forever/guide/classes/priest/shadow/enchants-consumables", "https://news.blizzard.com/en-us/article/24301514/world-of-warcraft-forever-class-deep-dives-priest-and-warrior", "https://news.blizzard.com/en-us/article/24315281/wow-forever-hotfixes-november-6-2026" },
    },
    {
      id = "reagents-codex",
      title = "Reagents, candles and Codex books",
      body = "The group 'Prayer' buffs need candles and books. Prayer of Fortitude is taught by Codex books (rank 1 at 48, rank 2 at 60) and uses Holy Candles (rank 1) or Sacred Candles. Prayer of Spirit and Prayer of Shadow Protection use Sacred Candles. Reagent vendors in the capital cities sell candles.",
      unconfirmed = false,
      flag = "",
      sources = { "https://db.icy-veins.com/wow-forever/spells/21562", "https://db.icy-veins.com/wow-forever/spells/27683", "https://db.icy-veins.com/wow-forever/items/17028", "https://db.icy-veins.com/wow-forever/items/17029", "https://www.icy-veins.com/wow-forever/shadow-priest-leveling" },
    },
    {
      id = "buffs",
      title = "Your buffs",
      body = "Power Word: Fortitude (Stamina) and Divine Spirit (Spirit) last an hour; give them to everyone. Shadow Protection adds Shadow Resistance. Inner Fire is your own armor buff with 20 charges. Camp buffs don't stack with class buffs: the First Aid Kit doesn't stack with Fortitude, and the Faction Banner doesn't stack with Divine Spirit.",
      unconfirmed = false,
      flag = "",
      sources = { "https://www.icy-veins.com/wow-forever/shadow-priest-leveling", "https://www.wowhead.com/forever/guide/classes/priest/discipline/healer-abilities", "https://www.wowhead.com/forever/guide/classes/priest/shadow/leveling-tips" },
    },
    {
      id = "racial-class-spells",
      title = "Racial Priest spells",
      body = "Each Priest race gets two exclusive spells from class quests at 10 and 20: Human (Divine Grace, Feedback), Dwarf (Desperate Prayer, Chastise), Gnome (Confounding Flash, Contingency Plan), Night Elf (Starshards, Elune's Grace), Troll (Hex of Weakness, Shadowguard) and Undead (Touch of Weakness, Dark Sacrifice). Skyborne can't be Priests.",
      unconfirmed = false,
      flag = "",
      sources = { "https://news.blizzard.com/en-us/article/24301514/world-of-warcraft-forever-class-deep-dives-priest-and-warrior", "https://www.icy-veins.com/wow-forever/priest-class-quests", "https://www.icy-veins.com/wow-forever/race-guide" },
    },
    {
      id = "prayer-of-healing-target",
      title = "Prayer of Healing targets a party",
      body = "In Forever, Prayer of Healing heals the party of whoever you target, not your own party. Target someone in the group that needs healing.",
      unconfirmed = false,
      flag = "",
      sources = { "https://news.blizzard.com/en-us/article/24301514/world-of-warcraft-forever-class-deep-dives-priest-and-warrior", "https://www.wowhead.com/forever/guide/classes/priest/holy/rotation-cooldowns-pve-healer" },
    },
    {
      id = "renew-stacking",
      title = "Renews stack between Priests",
      body = "In Forever, Renews from several Priests can all be on the same target at once, so two Priests don't have to coordinate them.",
      unconfirmed = false,
      flag = "",
      sources = { "https://news.blizzard.com/en-us/article/24301514/world-of-warcraft-forever-class-deep-dives-priest-and-warrior", "https://us.forums.blizzard.com/en/wow/t/wow-forever-beta-development-notes-%E2%80%93-updated-november-2/2360696" },
    },
  },
  roles = {
    {
      id = "dungeon-healer",
      title = "Healing a dungeon",
      body = "Most of your healing goes on the tank. Keep Renew up, use Heal as your efficient heal and Flash Heal when the tank is about to die. Shield the tank when you have spare mana; tanks still gain rage through the absorb. If you run out of mana the group usually dies, so start slow with a new group.",
      unconfirmed = false,
      flag = "",
      sources = { "https://www.wowhead.com/forever/guide/classes/priest/holy/rotation-cooldowns-pve-healer", "https://www.wowhead.com/forever/guide/classes/priest/discipline/rotation-cooldowns-pve-healer", "https://www.icy-veins.com/wow-forever/discipline-priest-leveling", "https://news.blizzard.com/en-us/article/24301514/world-of-warcraft-forever-class-deep-dives-priest-and-warrior" },
    },
    {
      id = "shadow-dps-in-groups",
      title = "Shadow damage in groups",
      body = "Keep your DoTs up, use Mind Blast and Shadow Word: Death on cooldown, keep Vampiric Embrace on the main target and fill with full Mind Flay channels. Watch threat: Mind Blast and Devouring Plague cause a lot. Below 40, healers are scarce, so be ready to heal.",
      unconfirmed = false,
      flag = "",
      sources = { "https://www.wowhead.com/forever/guide/classes/priest/shadow/rotation-cooldowns-pve-dps", "https://www.icy-veins.com/wow-forever/shadow-priest-ranged-dps-pve-guide", "https://www.wowhead.com/forever/guide/classes/priest/shadow/leveling-tips" },
    },
    {
      id = "buffing-the-group",
      title = "Buff everyone",
      body = "Give every group member Power Word: Fortitude, and give mana users Divine Spirit. Use Shadow Protection before Shadow-heavy fights. At higher levels the Prayer versions buff a whole party with candles. Rebuffing after a wipe takes time; the Quick and the Dead Legacy talent helps.",
      unconfirmed = false,
      flag = "",
      sources = { "https://www.icy-veins.com/wow-forever/shadow-priest-leveling", "https://www.wowhead.com/forever/guide/classes/priest/shadow/leveling-tips", "https://www.wowhead.com/forever/guide/classes/priest/discipline/healer-abilities" },
    },
    {
      id = "dispel-cure",
      title = "Dispel and cure",
      body = "Dispel Magic removes magic debuffs from allies (or buffs from enemies). Cure Disease and Abolish Disease remove diseases. Not every debuff is worth the mana; dispel the dangerous ones and the ones that will cost more mana to heal through.",
      unconfirmed = false,
      flag = "",
      sources = { "https://www.icy-veins.com/wow-forever/discipline-priest-leveling", "https://www.icy-veins.com/wow-forever/holy-priest-leveling", "https://www.icy-veins.com/wow-forever/shadow-priest-ranged-dps-pve-guide" },
    },
    {
      id = "mana-breaks",
      title = "Ask for mana breaks",
      body = "Healing has a large mana component. Let the group know when you need to drink before the next pull, and use your wand during quiet moments instead of damage spells.",
      unconfirmed = true,
      flag = "Announcing drink breaks is general group etiquette, not stated in the sources",
      sources = { "https://www.wowhead.com/forever/guide/classes/priest/discipline/rotation-cooldowns-pve-healer", "https://www.icy-veins.com/wow-forever/discipline-priest-leveling", "https://www.wowhead.com/forever/guide/classes/priest/shadow/leveling-tips" },
    },
    {
      id = "fear-ward",
      title = "Fear Ward the tank",
      body = "Every Priest gets Fear Ward at 20. Before a pull or boss that fears, put it on the tank. It blocks the next fear and is then used up.",
      unconfirmed = false,
      flag = "",
      sources = { "https://news.blizzard.com/en-us/article/24301514/world-of-warcraft-forever-class-deep-dives-priest-and-warrior", "https://www.wowhead.com/forever/guide/classes/priest/discipline/rotation-cooldowns-pve-healer", "https://www.wowhead.com/forever/guide/classes/priest/shadow/abilities" },
    },
    {
      id = "shackle-undead",
      title = "Shackle Undead",
      body = "Against Undead enemies, you can shackle one to take it out of the pull. Damage breaks it and it can be resisted, so mark the target and tell the group not to hit it.",
      unconfirmed = true,
      flag = "Marking targets and telling the group is general etiquette",
      sources = { "https://www.icy-veins.com/wow-forever/discipline-priest-leveling", "https://www.icy-veins.com/wow-forever/holy-priest-leveling", "https://www.wowhead.com/forever/guide/classes/priest/shadow/abilities" },
    },
    {
      id = "mind-control-caution",
      title = "Mind Control with care",
      body = "While you channel Mind Control you can't heal. The target can resist at the start or break free later. Ask yourself whether removing that enemy prevents more damage than you could heal in the same time.",
      unconfirmed = false,
      flag = "",
      sources = { "https://www.icy-veins.com/wow-forever/holy-priest-healer-pve-guide", "https://www.icy-veins.com/wow-forever/discipline-priest-leveling" },
    },
    {
      id = "psychic-scream-caution",
      title = "Don't fear in dungeons",
      body = "Psychic Scream sends enemies running in random directions, and they often pull more enemies. Use it only to save the group in an emergency.",
      unconfirmed = false,
      flag = "",
      sources = { "https://www.icy-veins.com/wow-forever/shadow-priest-leveling", "https://www.icy-veins.com/wow-forever/discipline-priest-leveling", "https://www.icy-veins.com/wow-forever/holy-priest-leveling" },
    },
    {
      id = "power-infusion",
      title = "Power Infusion",
      body = "Discipline's capstone boosts a target's spell damage and healing. Put it on an allied caster during an important damage window.",
      unconfirmed = false,
      flag = "",
      sources = { "https://www.icy-veins.com/wow-forever/discipline-priest-leveling", "https://www.wowhead.com/forever/guide/classes/priest/discipline/rotation-cooldowns-pve-healer" },
    },
    {
      id = "killing-blows",
      title = "Killing blows and Spirit Tap",
      body = "In dungeons, Spirit Tap needs your killing blow. Coordinate with the group when you can, or let Vampiric Embrace trigger it.",
      unconfirmed = false,
      flag = "",
      sources = { "https://www.wowhead.com/forever/guide/classes/priest/shadow/leveling-tips" },
    },
    {
      id = "raid-rules",
      title = "Raid rules in Forever",
      body = "Raids open Dec 9: Barrow Deeps (10), Hyjal Summit (20) and Onyxia's Lair (40). World buffs are removed inside raids, there are no Heroic or flex modes, and item stats stay hidden until someone first loots the item.",
      unconfirmed = false,
      flag = "",
      sources = { "https://www.icy-veins.com/wow-forever/raid-overview", "https://www.icy-veins.com/wow-forever/roadmap" },
    },
  },
  leveling = {
    Shadow = {
      {
        title = "Talent path",
        body = "Take Wand Specialization first. Then go into Shadow: Spirit Tap, Mind Flay (20), Vampiric Embrace, Devouring Contagion, Shadowform (40), and Meditation late. Icy Veins prefers Blackout to Shadow Focus while leveling.",
        unconfirmed = false,
        flag = "",
        sources = { "https://www.icy-veins.com/wow-forever/shadow-priest-leveling" },
      },
      {
        title = "Respec-at-40 route",
        body = "Another option: level as Discipline (Wand Specialization, Spirit Tap, Twin Disciplines, Mental Strength, Meditation) for better early mana, then respec at a trainer at 40 to get Shadowform. Icy Veins says it costs 1 gold.",
        unconfirmed = false,
        flag = "",
        sources = { "https://www.icy-veins.com/wow-forever/shadow-priest-leveling", "https://www.wowhead.com/forever/guide/classes/priest/shadow/leveling-tips" },
      },
      {
        title = "The fight script",
        body = "Buff up (Fortitude, Inner Fire), shield, open with Mind Blast, apply Shadow Word: Pain, then Devouring Plague and Mind Flay if your mana allows. Finish with your wand. Before Mind Flay, open with Smite.",
        unconfirmed = false,
        flag = "",
        sources = { "https://www.icy-veins.com/wow-forever/shadow-priest-leveling", "https://www.wowhead.com/forever/guide/classes/priest/shadow/leveling-tips" },
      },
      {
        title = "Multi-dotting",
        body = "Shadow has no real area spell. When you're comfortable, put Shadow Word: Pain on several enemies and kill them one at a time, but watch your mana, Inner Fire charges and pushback.",
        unconfirmed = false,
        flag = "",
        sources = { "https://www.icy-veins.com/wow-forever/shadow-priest-leveling" },
      },
      {
        title = "Mana gets easier at 40",
        body = "Mana is hardest before 40. Vampiric Embrace makes Spirit Tap easier to trigger, and Shadowform halves the cost of Shadow spells.",
        unconfirmed = false,
        flag = "",
        sources = { "https://www.icy-veins.com/wow-forever/shadow-priest-ranged-dps-pve-guide", "https://www.icy-veins.com/wow-forever/shadow-priest-leveling" },
      },
    },
    Holy = {
      {
        title = "Group up or borrow Shadow talents",
        body = "Holy is great with a group but slow solo, with little damage and little area damage. Icy Veins suggests leveling with Shadow talents until you can do group content regularly.",
        unconfirmed = false,
        flag = "",
        sources = { "https://www.icy-veins.com/wow-forever/holy-priest-leveling", "https://www.icy-veins.com/wow-forever/holy-priest-healer-pve-guide" },
      },
      {
        title = "Core talents",
