        unconfirmed = false,
        flag = "",
        sources = { "https://www.icy-veins.com/wow-forever/holy-priest-leveling" },
      },
      {
        title = "Leveling rotation",
        body = "Buff up and shield, then Holy Fire, Smite as the enemy walks in, Mind Blast, Shadow Word: Pain, and wand to finish. Renew yourself while you wand.",
