        unconfirmed = false,
        flag = "",
        sources = { "https://www.icy-veins.com/wow-forever/holy-priest-leveling", "https://news.blizzard.com/en-us/article/24301514/world-of-warcraft-forever-class-deep-dives-priest-and-warrior" },
      },
      {
        title = "Healing milestones",
        body = "Heal at 16, Holy Nova (11 points) around 20, Holy Binding at 16 points, then Prayer of Healing, Greater Heal and Prayer of Mending (31 points) by about 40.",
        unconfirmed = false,
        flag = "",
        sources = { "https://www.icy-veins.com/wow-forever/holy-priest-leveling", "https://us.forums.blizzard.com/en/wow/t/wow-forever-beta-development-notes-%E2%80%93-updated-november-2/2360696", "https://news.blizzard.com/en-us/article/24301514/world-of-warcraft-forever-class-deep-dives-priest-and-warrior" },
      },
    },
    Discipline = {
      {
        title = "Easier solo than Holy",
        body = "Discipline has more damage talents than Holy, but healers still struggle solo. Group up for quests and dungeons when you can.",
        unconfirmed = false,
        flag = "",
        sources = { "https://www.icy-veins.com/wow-forever/discipline-priest-leveling", "https://www.icy-veins.com/wow-forever/discipline-priest-healer-pve-guide" },
      },
      {
        title = "Opening talents",
